def _ensure_loaded(self):
    # Double-checked lock: concurrent first dispatches must not both run
    # load_providers() and end up with duplicate provider objects.
    if not self._loaded:
        with self._load_lock:
            if not self._loaded:
                if self._providers is None:
                    self._providers = load_providers(role_filter="dispatch")
                self._loaded = True

@dataclass
class ProviderResponse:
    provider_id: str
    provider_name: str
    text: str = ""
    status: str = "success"       # success | timeout | error
    latency_ms: int = 0
    error_message: Optional[str] = None

    @property
    def ok(self) -> bool:
        return self.status == "success" and bool(self.text.strip())


